css:
.loader {
  position: relative;
  width: 56px;
  height: 46px;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  border-radius: 2px;
  background: #6366f1;
}
.loader i {
  position: absolute;
  top: 3px;
  width: 2px;
  border-radius: 2px;
  background: #c7d2fe;
  transform-origin: top center;
  animation: pend 1s ease-in-out infinite;
}
.loader i::after {
  content: "";
  position: absolute;
  bottom: -6px;
  left: 50%;
  width: 7px;
  height: 7px;
  margin-left: -3.5px;
  border-radius: 50%;
  background: #6366f1;
}
.loader i:nth-child(1) { left: 6px; height: 18px; animation-duration: 1s; }
.loader i:nth-child(2) { left: 17px; height: 24px; animation-duration: 1.12s; }
.loader i:nth-child(3) { left: 28px; height: 30px; animation-duration: 1.24s; }
.loader i:nth-child(4) { left: 39px; height: 24px; animation-duration: 1.36s; }
.loader i:nth-child(5) { left: 50px; height: 18px; animation-duration: 1.48s; }
@keyframes pend {
  0%, 100% { transform: rotate(24deg); }
  50% { transform: rotate(-24deg); }
}
